package com.noir.player;

import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.database.Cursor;
import android.provider.OpenableColumns;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.net.*;
import org.json.*;

public class MainActivity extends Activity {
 PlayerView view; public android.content.SharedPreferences prefs;
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("noir",0);view=new PlayerView(this);setContentView(view);applyLock();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);}
 public void applyLock(){boolean on=prefs.getBoolean("lock",false);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(on);setTurnScreenOn(false);}else if(on){getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED);}else{getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED);}}
 public void openFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/*"}).addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,7);}
 protected void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(r==7&&code==RESULT_OK&&data!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}String name="Local audio";try(Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(c.getColumnIndexOrThrow(OpenableColumns.DISPLAY_NAME));}remember(u.toString(),name);load(u.toString(),name);}}
 public void load(String uri,String title){String videoId=MediaLinks.youtubeId(uri);if(videoId!=null){startActivity(new Intent(this,YouTubeActivity.class).putExtra("id",videoId).putExtra("music","music.youtube.com".equalsIgnoreCase(Uri.parse(uri).getHost())));return;}if(MediaLinks.isYouTubeHost(uri)){Toast.makeText(this,"Paste a YouTube watch, Shorts or youtu.be video link",Toast.LENGTH_LONG).show();return;}startForegroundService(new Intent(this,PlaybackService.class).setAction("load").putExtra("uri",uri).putExtra("title",title));}
 void remember(String uri,String name){try{JSONArray a=new JSONArray(prefs.getString("library","[]"));for(int j=0;j<a.length();j++)if(a.getJSONObject(j).getString("uri").equals(uri))return;a.put(new JSONObject().put("uri",uri).put("title",name));prefs.edit().putString("library",a.toString()).apply();}catch(Exception ignored){}}
 public void library(){try{JSONArray a=new JSONArray(prefs.getString("library","[]"));String[] names=new String[a.length()+1];names[0]="+ Import audio or video";for(int j=0;j<a.length();j++)names[j+1]=a.getJSONObject(j).getString("title");new AlertDialog.Builder(this).setTitle("Offline & local library").setItems(names,(d,w)->{if(w==0)openFile();else try{JSONObject t=a.getJSONObject(w-1);load(t.getString("uri"),t.getString("title"));}catch(Exception ignored){}}).show();}catch(Exception e){openFile();}}
 public void online(){new AlertDialog.Builder(this).setTitle("Online inside Pulse").setItems(new String[]{"Browse YouTube","Browse YouTube Music","Paste YouTube or direct media URL"},(dialog,choice)->{if(choice<2)startActivity(new Intent(this,YouTubeActivity.class).putExtra("music",choice==1));else openOnlineUrl();}).show();}
 public void openOnlineUrl(){LinearLayout box=new LinearLayout(this);box.setPadding(40,12,40,12);box.setOrientation(LinearLayout.VERTICAL);EditText url=new EditText(this);url.setHint("YouTube / Music link or HTTPS media URL");url.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_VARIATION_URI);EditText name=new EditText(this);name.setHint("Track title");box.addView(url);box.addView(name);new AlertDialog.Builder(this).setTitle("Open online media").setMessage("YouTube links stay inside Pulse in the web player. Direct HTTPS audio/video streams use the native Pulse player.").setView(box).setPositiveButton("Stream",(d,w)->{String u=url.getText().toString().trim();if(valid(u))load(u,name.length()>0?name.getText().toString():"Online media");}).setNeutralButton("Download",(d,w)->{String u=url.getText().toString().trim();if(MediaLinks.isYouTubeHost(u)){Toast.makeText(this,"YouTube downloads are not supported",Toast.LENGTH_LONG).show();return;}if(valid(u))download(u,name.length()>0?name.getText().toString():"Downloaded audio");}).setNegativeButton("Cancel",null).show();}
 boolean valid(String u){try{URI x=new URI(u);if("https".equalsIgnoreCase(x.getScheme())&&x.getHost()!=null)return true;}catch(Exception ignored){}Toast.makeText(this,"Enter a valid HTTPS audio URL",Toast.LENGTH_LONG).show();return false;}
 void download(String u,String name){Toast.makeText(this,"Downloading…",Toast.LENGTH_SHORT).show();new Thread(()->{File f=new File(getFilesDir(),"audio-"+System.currentTimeMillis());try{String next=u;HttpURLConnection con=null;for(int i=0;i<6;i++){URL target=new URL(next);if(!"https".equals(target.getProtocol()))throw new IOException("HTTPS required");con=(HttpURLConnection)target.openConnection();con.setConnectTimeout(15000);con.setReadTimeout(20000);con.setInstanceFollowRedirects(false);int status=con.getResponseCode();if(status>=300&&status<400){String loc=con.getHeaderField("Location");next=new URL(target,loc).toString();con.disconnect();continue;}if(status!=200)throw new IOException("HTTP "+status);break;}if(con==null||con.getResponseCode()!=200)throw new IOException("Too many redirects");String type=con.getContentType();if(type!=null&&(type.contains("mpegurl")||type.contains("dash+xml")))throw new IOException("Adaptive streams can be played online; offline manifest downloads are not supported");if(type!=null&&type.contains("text/html"))throw new IOException("Link is a web page");try(InputStream in=con.getInputStream();OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[16384];long total=0;int n;while((n=in.read(buf))!=-1){total+=n;if(total>250L*1024*1024)throw new IOException("Download limit is 250 MB");out.write(buf,0,n);}}finally{con.disconnect();}runOnUiThread(()->{remember(Uri.fromFile(f).toString(),name);Toast.makeText(this,"Saved to offline library",Toast.LENGTH_LONG).show();});}catch(Exception e){f.delete();runOnUiThread(()->Toast.makeText(this,"Download failed: "+e.getMessage(),Toast.LENGTH_LONG).show());}}).start();}
 public void settings(){String[] options={"White","Red","Yellow","Blue","Purple","Red / Yellow / White","Blue / Purple / White","Dot matrix: "+(prefs.getBoolean("dots",false)?"ON":"OFF"),"Button: "+(prefs.getBoolean("filled",true)?"Filled":"Outline"),"Show over lock screen: "+(prefs.getBoolean("lock",false)?"ON":"OFF"),"Watch current video / Audio-only option"};new AlertDialog.Builder(this).setTitle("Make it yours").setItems(options,(d,w)->{if(w<7)prefs.edit().putInt("theme",w).apply();if(w==7)prefs.edit().putBoolean("dots",!prefs.getBoolean("dots",false)).apply();if(w==8)prefs.edit().putBoolean("filled",!prefs.getBoolean("filled",true)).apply();if(w==10){if(PlaybackService.current==null){Toast.makeText(this,"Open a local video or direct video stream first",Toast.LENGTH_LONG).show();}else startActivity(new Intent(this,VideoActivity.class));}if(w==9){prefs.edit().putBoolean("lock",!prefs.getBoolean("lock",false)).apply();applyLock();new AlertDialog.Builder(this).setMessage("When enabled, keep Pulse Media Player open and lock your phone to use the full-screen player. Android may show the system lock screen first. Pulse Media Player does not bypass device security or force itself open from the background.").setPositiveButton("OK",null).show();}view.invalidate();}).show();}
}
